      SUBROUTINE VPRINTCC     PRINT VARY CODESCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA2B.CIN'      INCLUDE 'DATA2D.CIN'      INCLUDE 'DBEAM.CIN'      INCLUDE 'DBEND.CIN'      INCLUDE 'DCENT.CIN'      INCLUDE 'DCVTY.CIN'      INCLUDE 'DDRFT.CIN'      INCLUDE 'DETA.CIN'      INCLUDE 'DHKICK.CIN'      INCLUDE 'DKICK.CIN'      INCLUDE 'DMIS.CIN'      INCLUDE 'DOCT.CIN'      INCLUDE 'DQUAD.CIN'      INCLUDE 'DRBND.CIN'      INCLUDE 'DROT.CIN'      INCLUDE 'DSEXT.CIN'      INCLUDE 'DSHIFT.CIN'      INCLUDE 'DSOLE.CIN'      INCLUDE 'DSPEC.CIN'      INCLUDE 'DSROT.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'RDCHAR.CIN'      INCLUDE 'VFLAG.CIN'C ---------------------------------------------------------------------      CHARACTER*1     ICHAR(30)      CHARACTER*8     CHAR(12)      INTEGER         IDATA, IJ, ISIG, IVA, IVARY      INTEGER         J, JV, JV1, JV2      INTEGER         K, KV, LL, LX, NIV, NV      INTEGER         IARR(6)      REAL            PARAM      EXTERNAL        IDATA      DATA IARR       /0,0,1,3,6,10/CC     IDENTIFY VARY CODESC      IF (.NOT. (PRON .AND. ELPR)) GO TO 200      IF (TYPE .EQ. 10) GO TO 200      IVA = 0      LX = 0CC     COUPLED VARIED CODES -- PRINT OUT AS VARY CODESC      IF (.NOT. VFLAG) GO TO 50      KV = NIV(TYPE)      IF (KV .EQ. 0) GO TO 200      IF (TYPE .NE. 14) KV = MAX0(KV,NPARMS)C      DO 20 J = 1, 30   20 ICHAR(J) = BLANKC      DO 30 JV = 1, KV      K = I + JV      ISIG = TIE(K)      IF (ISIG .GE. 99) ISIG = 0      IVARY = IABS(ISIG)      LX = LX + 1      IF (ISIG .LT. 0) ICHAR(LX) = MINUS      LX = LX + 1      IF (IVARY .NE. 0) THEN        IVARY = VSTOR(IVARY)        IVA = 1      ENDIF      ICHAR(LX) = TABLE(IVARY + 1)   30 CONTINUECC     PRINT VARY CODESC      IF (IVA .EQ. 0) GO TO 200      WRITE (NOUT,9500) ICHAR      GO TO 100CC     VARY CODES (NO OLD-STYLE COUPLING) -- IDENTIFY VARIED PARAMETERSC   50 IF (TYPE .GE. 50) GO TO 200      KV = NV(TYPE)      IF (KV .EQ. 0) GO TO 200      IF (TYPE .NE. 14) KV = MAX0(KV,NPARMS)C      DO 70 JV = 1, KV      IJ = IPTOJ(JV)      IF (IJ .EQ. 0) GO TO 70      K = I + IJ      ISIG = TIE(K)      IF (ISIG .GE. 99) ISIG = 0      IVARY = IABS(ISIG)      IF (IVARY .NE. 0) THEN        LX = LX + 1        IVARY = VSTOR(IVARY)        IVA = 1        CHAR(LX) = ' '        IF (TYPE .EQ. 1) CHAR(LX) = DBEAM(JV)(1:8)        IF (TYPE .EQ. 2) CHAR(LX) = DROT(JV)(1:8)        IF (TYPE .EQ. 3) CHAR(LX) = DDRFT(JV)(1:8)        IF (TYPE .EQ. 4) CHAR(LX) = DBEND(JV)(1:8)        IF (TYPE .EQ. 5) CHAR(LX) = DQUAD(JV)(1:8)        IF (TYPE .EQ. 7) CHAR(LX) = DCENT(JV)(1:8)        IF (TYPE .EQ. 8) CHAR(LX) = DMIS(JV)(1:8)        IF (TYPE .EQ. 11) CHAR(LX) = DCVTY(JV)(1:8)        IF (TYPE .EQ. 12) THEN          CHAR(LX)(1:1) = 'C'          JV1 = 0   60     JV1 = JV1 + 1          IF (JV .GT. IARR(JV1+1)) GO TO 60          JV2 = JV - IARR(JV1)          CHAR(LX)(2:2) = TABLE(JV1+1)          CHAR(LX)(3:3) = TABLE(JV2+1)        ENDIF        IF (TYPE .EQ. 14) THEN          CHAR(LX)(1:1) = 'R'          CHAR(LX)(2:2) = TABLE(INT(DATA(I+7))+1)          CHAR(LX)(3:3) = TABLE(JV+1)        ENDIF        IF (TYPE .EQ. 16) CHAR(LX) = DSPEC(INT(DATA(I+1))+3)(1:8)        IF (TYPE .EQ. 18) CHAR(LX) = DSEXT(JV)(1:8)        IF (TYPE .EQ. 19) CHAR(LX) = DSOLE(JV)(1:8)        IF (TYPE .EQ. 20) CHAR(LX) = DSROT(JV)(1:8)        IF (TYPE .EQ. 25) CHAR(LX) = DOCT(JV)(1:8)        IF (TYPE .EQ. 27) CHAR(LX) = DETA(JV)(1:8)        IF (TYPE .EQ. 28 .OR. TYPE .EQ. 29) CHAR(LX) = DRBND(JV)(1:8)        IF (TYPE .EQ. 34) CHAR(LX) = DQUAD(JV)(1:8)        IF (TYPE .EQ. 35 .OR. TYPE .EQ. 36) CHAR(LX) = DHKICK(JV)(1:8)        IF (TYPE .EQ. 42) CHAR(LX) = DKICK(JV)(1:8)        IF (TYPE .EQ. 43) CHAR(LX) = DSHIFT(JV)(1:8)      ENDIF   70 CONTINUECC     PRINT VARY CODESC      IF (IVA .EQ. 0) GO TO 200      WRITE (NOUT,9501) (CHAR(LL), LL = 1, LX)CC     PRINT PRECISE VALUES OF VARIED PARAMETERSC  100 IF (.NOT. UNRO) GO TO 200      DO 110 JV = 1, KV      K = I + IPTOJ(JV)  105 ISIG = TIE(K)      IF (ISIG .EQ. 100) THEN        K = IDATA(K)        GO TO 105      ENDIF      IF (ISIG .NE. 0) THEN        PARAM = DATA(K)        WRITE (NOUT,9502) PARAM      ENDIF  110 CONTINUE  200 RETURNC 9500 FORMAT (1H ,12X,'VARY CODE = ',30A1) 9501 FORMAT (1H ,12X,'VARIED:  ',12(A8,2X)) 9502 FORMAT (1H ,12X,'VARIED PARAMETER',3X,F18.10)      END